}

html, body {
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, sans-serif;
  background: var(--bg);
  color: var(--text);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

a.skip-link {
  position: absolute;
  left: 12px;
  top: -40px;
  background: var(--surface);
  color: var(--text);
  padding: 8px 12px;
  border-radius: var(--radius-sm);
  border: 2px solid var(--focus);
  z-index: 1000;
  text-decoration: none;
  font-weight: 600;
}
a.skip-link:focus {
  top: 12px;
}

.site-header {
  background: var(--surface);
  border-bottom: 1px solid var(--border);
  padding: 16px 24px;
}
.site-header .inner {
  max-width: 1100px;
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
}
.brand {
  font-weight: 700;
  font-size: 1.05rem;
  letter-spacing: -0.01em;
}

.site-nav ul {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  gap: 4px;
}
.site-nav a {
  display: inline-block;
  padding: 8px 12px;
  text-decoration: none;
  color: var(--text-muted);
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
}
.site-nav a:hover { color: var(--text); background: var(--surface-2); }
.site-nav a:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

main {
  max-width: 1100px;
  margin: 0 auto;
  padding: 32px 24px 64px;
}

.page-title {
  margin: 0 0 4px;
  font-size: 1.6rem;
  letter-spacing: -0.02em;
}
.page-subtitle {
  margin: 0 0 28px;
  color: var(--text-muted);
  font-size: 0.95rem;
}

.preview-card {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.preview-image {
  display: block;
  width: 100%;
  height: auto;
  max-height: 520px;
  object-fit: cover;
  background: var(--surface-2);
}

.preview-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 16px 24px;
  align-items: flex-start;
  justify-content: space-between;
  padding: 20px 24px;
  border-top: 1px solid var(--border);
}

.meta-text {
  min-width: 0;
}
.meta-title {
  margin: 0 0 4px;
  font-size: 1.05rem;
  font-weight: 600;
}
.meta-details {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.875rem;
}

.preview-actions {
  display: flex;
  gap: 8px;
  flex-wrap: wrap;
}

.btn {
  appearance: none;
  font: inherit;
  font-weight: 600;
  font-size: 0.9rem;
  padding: 9px 16px;
  border-radius: var(--radius-sm);
  border: 1px solid var(--border-strong);
  background: var(--surface);
  color: var(--text);
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  gap: 8px;
  transition: background-color 120ms, border-color 120ms, color 120ms;
}
.btn:hover { background: var(--surface-2); }
.btn:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 2px;
}

.btn-primary {
  background: var(--primary);
  border-color: var(--primary);
  color: #fff;
}
.btn-primary:hover { background: var(--primary-hover); border-color: var(--primary-hover); }

.btn-danger {
  background: var(--danger);
  border-color: var(--danger);
  color: #fff;
}
.btn-danger:hover { background: var(--danger-hover); border-color: var(--danger-hover); }

.btn-ghost-danger {
  color: var(--danger);
  border-color: var(--border-strong);
  background: var(--surface);
}
.btn-ghost-danger:hover { background: var(--danger-bg); border-color: var(--danger); }

.btn .icon {
  width: 16px;
  height: 16px;
  flex: none;
}

/* Dialog */
.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(15, 23, 42, 0.55);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 16px;
  z-index: 50;
  animation: fade 140ms ease-out;
}

@keyframes fade {
  from { opacity: 0; }
  to { opacity: 1; }
}
@keyframes pop {
  from { opacity: 0; transform: translateY(8px) scale(0.98); }
  to   { opacity: 1; transform: translateY(0) scale(1); }
}

.dialog {
  background: var(--surface);
  border-radius: var(--radius);
  border: 1px solid var(--border);
  box-shadow: var(--shadow-lg);
  width: 100%;
  max-width: 460px;
  padding: 24px;
  animation: pop 160ms ease-out;
  outline: none;
}

.dialog-header {
  display: flex;
  gap: 14px;
  align-items: flex-start;
}

.dialog-icon {
  width: 40px;
  height: 40px;
  border-radius: 50%;
  background: var(--danger-bg);
  color: var(--danger);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  flex: none;
}
.dialog-icon svg { width: 22px; height: 22px; }

.dialog-title {
  margin: 0 0 4px;
  font-size: 1.1rem;
  font-weight: 600;
  letter-spacing: -0.01em;
}

.dialog-desc {
  margin: 0;
  color: var(--text-muted);
  font-size: 0.92rem;
}
.dialog-desc strong { color: var(--text); }

.dialog-actions {
  margin-top: 22px;
  display: flex;
  justify-content: flex-end;
  gap: 8px;
  flex-wrap: wrap;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.status-region {
  position: fixed;
  bottom: 24px;
  left: 50%;
  transform: translateX(-50%);
  background: #0f172a;
  color: #fff;
  padding: 10px 16px;
  border-radius: var(--radius-sm);
  font-size: 0.9rem;
  box-shadow: var(--shadow-lg);
  z-index: 60;
}

@media (max-width: 520px) {
  .preview-meta { flex-direction: column; align-items: stretch; }
  .preview-actions { justify-content: flex-end; }
}

@media (forced-colors: active) {
  .btn { border-color: ButtonBorder; color: ButtonText; background: ButtonFace; }
  .btn-primary, .btn-danger { background: ButtonFace; color: ButtonText; border-color: ButtonBorder; }
  .dialog { border-color: CanvasText; }
  .dialog-icon { color: CanvasText; background: Canvas; border: 1px solid CanvasText; }
  .btn:focus-visible, .site-nav a:focus-visible {
    outline: 2px solid Highlight;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dialog-backdrop, .dialog { animation: none; }
  .btn { transition: none; }
}
