const { useState, useEffect, useRef, useCallback } = React;

function Icon({ name, className = "icon", ...props }) {
  const paths = {
    download: <path d="M12 3v12m0 0l-4-4m4 4l4-4M5 21h14" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" />,
    trash: <path d="M4 7h16M9 7V5a2 2 0 012-2h2a2 2 0 012 2v2m-7 0v12a2 2 0 002 2h6a2 2 0 002-2V7M10 11v6M14 11v6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" />,
    warning: <path d="M12 3l10 18H2L12 3zm0 6v5m0 3v.01" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" fill="none" />,
  };
  return (
    <svg className={className} viewBox="0 0 24 24" aria-hidden="true" focusable="false" {...props}>
      {paths[name]}
    </svg>
  );
}

function ConfirmDeleteDialog({ open, imageName, onCancel, onConfirm }) {
  const dialogRef = useRef(null);
  const cancelBtnRef = useRef(null);
  const previouslyFocused = useRef(null);

  useEffect(() => {
    if (!open) return;

    previouslyFocused.current = document.activeElement;
    // Focus the safer (cancel) action by default
    const t = setTimeout(() => cancelBtnRef.current?.focus(), 0);

    const onKey = (e) => {
      if (e.key === "Escape") {
        e.stopPropagation();
        onCancel();
      } else if (e.key === "Tab") {
        // Focus trap
        const focusables = dialogRef.current?.querySelectorAll(
          'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])'
        );
        if (!focusables || focusables.length === 0) return;
        const first = focusables[0];
        const last = focusables[focusables.length - 1];
        if (e.shiftKey && document.activeElement === first) {
          e.preventDefault(); last.focus();
        } else if (!e.shiftKey && document.activeElement === last) {
          e.preventDefault(); first.focus();
        }
      }
    };
    document.addEventListener("keydown", onKey);
    const prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";

    return () => {
      clearTimeout(t);
      document.removeEventListener("keydown", onKey);
      document.body.style.overflow = prevOverflow;
      previouslyFocused.current?.focus?.();
    };
  }, [open, onCancel]);

  if (!open) return null;

  const onBackdropClick = (e) => {
    if (e.target === e.currentTarget) onCancel();
  };

  return (
    <div className="dialog-backdrop" onMouseDown={onBackdropClick}>
      <div
        className="dialog"
        role="alertdialog"
        aria-modal="true"
        aria-labelledby="confirm-title"
        aria-describedby="confirm-desc"
        ref={dialogRef}
        tabIndex={-1}
      >
        <div className="dialog-header">
          <span className="dialog-icon" aria-hidden="true">
            <Icon name="warning" className="" />
          </span>
          <div>
            <h2 className="dialog-title" id="confirm-title">Delete this image?</h2>
            <p className="dialog-desc" id="confirm-desc">
              <strong>{imageName}</strong> will be permanently removed from your library.
              This action cannot be undone.
            </p>
          </div>
        </div>
        <div className="dialog-actions">
          <button type="button" className="btn" ref={cancelBtnRef} onClick={onCancel}>
            Cancel
          </button>
          <button type="button" className="btn btn-danger" onClick={onConfirm}>
            <Icon name="trash" />
            Delete image
          </button>
        </div>
      </div>
    </div>
  );
}

function ImagePreviewPage() {
  const [dialogOpen, setDialogOpen] = useState(false);
  const [deleted, setDeleted] = useState(false);
  const [status, setStatus] = useState("");

  const image = {
    name: "Sunrise over the ridge.jpg",
    details: "3024 × 4032 · 2.4 MB · Added Apr 12, 2025",
    src: "https://images.unsplash.com/photo-1506744038136-46273834b3fb?auto=format&fit=crop&w=1400&q=80",
    alt: "A misty mountain ridge at sunrise with warm orange light reflecting on a calm lake below."
  };

  const openDialog = useCallback(() => setDialogOpen(true), []);
  const closeDialog = useCallback(() => setDialogOpen(false), []);

  const confirmDelete = useCallback(() => {
    setDialogOpen(false);
    setDeleted(true);
    setStatus(`"${image.name}" was deleted from your library.`);
    setTimeout(() => setStatus(""), 4000);
  }, [image.name]);

  return (
    <>
      <a className="skip-link" href="#main">Skip to main content</a>
      <header className="site-header">
        <div className="inner">
          <div className="brand">Lumen Library</div>
          <nav className="site-nav" aria-label="Primary">
            <ul>
              <li><a href="#library">Library</a></li>
              <li><a href="#albums">Albums</a></li>
              <li><a href="#shared">Shared</a></li>
            </ul>
          </nav>
        </div>
      </header>

      <main id="main">
        <h1 className="page-title">Image preview</h1>
        <p className="page-subtitle">Review your photo and manage it from one place.</p>

        {!deleted ? (
          <article className="preview-card" aria-labelledby="image-name">
            <img className="preview-image" src={image.src} alt={image.alt} />
            <div className="preview-meta">
              <div className="meta-text">
                <h2 className="meta-title" id="image-name">{image.name}</h2>
                <p className="meta-details">{image.details}</p>
              </div>
              <div className="preview-actions">
                <button type="button" className="btn">
                  <Icon name="download" />
                  Download
                </button>
                <button
                  type="button"
                  className="trigger btn btn-ghost-danger"
                  onClick={openDialog}
                  aria-haspopup="dialog"
                  aria-expanded={dialogOpen}
                >
                  <Icon name="trash" />
                  Delete
                </button>
              </div>
            </div>
          </article>
        ) : (
          <article className="preview-card" aria-live="polite">
            <div style={{ padding: "48px 24px", textAlign: "center" }}>
              <h2 style={{ margin: "0 0 8px" }}>Image deleted</h2>
              <p style={{ margin: 0, color: "var(--text-muted)" }}>
                {image.name} has been removed from your library.
              </p>
            </div>
          </article>
        )}
      </main>

      <ConfirmDeleteDialog
        open={dialogOpen}
        imageName={image.name}
        onCancel={closeDialog}
        onConfirm={confirmDelete}
      />

      <div role="status" aria-live="polite" className="sr-only">
        {status}
      </div>
      {status && <div className="status-region" aria-hidden="true">{status}</div>}
    </>
  );
}

ReactDOM.createRoot(document.getElementById("root")).render(<ImagePreviewPage />);

